(()=>{'use strict';
const KEY='kpResourcesV1',TOPICS=['KP Fundamentals','Zodiac Signs and Planets','Nakshatras and Sub Lords','Cusps and Bhavas','Four-fold Significators','Six-fold Significators','Four-step Theory','Ruling Planets','Vimshottari Dasha','Event Promise','Dasha Promise','Transits and Sun Gochar','Horary Astrology','Birth Time Rectification','Nadi Astrology','Education and Profession','Health References','Matchmaking','Ayanamsha and Ephemeris','Raphael Table of Houses'];
let resources=Object.create(null),selected='',editing=false,renaming=false,draft='',newTopic='',root,status='';
try{const raw=localStorage.getItem(KEY);if(raw===null)TOPICS.forEach(t=>resources[t]='');else{const saved=JSON.parse(raw);if(saved&&typeof saved==='object'&&!Array.isArray(saved))Object.entries(saved).forEach(([k,v])=>{if(k.trim()&&typeof v==='string')resources[k]=v;});}}catch(_){TOPICS.forEach(t=>resources[t]='');status='Browser storage is unavailable. Save a text file to keep your notes.';}
const has=t=>Object.hasOwn(resources,t),$=id=>root.querySelector('#'+id);
function persist(message){try{localStorage.setItem(KEY,JSON.stringify(resources));status=message||'Saved in this browser.';}catch(_){status='Browser storage is unavailable. Save a text file to keep your notes.';}if(root?.isConnected)$('resource-status').textContent=status;}
function remember(){if(root?.isConnected){draft=$('resource-notes').value;newTopic=$('resource-new-topic').value;}}
function choices(){const select=$('resource-topic');select.replaceChildren();Object.keys(resources).forEach(t=>{const n=document.createElement('option');n.value=t;n.textContent=t;select.append(n);});if(!has(selected))selected=Object.keys(resources)[0]||'';select.value=selected;}
function render(){choices();$('resource-notes').value=draft;$('resource-notes').readOnly=!editing||!selected;$('resource-new-topic').value=newTopic;$('resource-topic-name-label').textContent=renaming?'Edit topic / subtopic name':'New topic / subtopic';$('resource-add').textContent=renaming?'Save topic name':'Add subtopic';$('resource-cancel-topic').hidden=!renaming;$('resource-status').textContent=status;for(const id of ['resource-edit-note','resource-delete-note','resource-edit-topic','resource-delete-topic'])$(id).disabled=!selected;$('resource-save').disabled=!selected||!editing;for(const id of ['resource-preview','resource-print','resource-download'])$(id).disabled=!Object.keys(resources).length;}
function saveDraft(){if(has(selected))resources[selected]=draft;}
function plainText(scope=$('resource-export-scope').value){remember();const topics=scope==='all'?Object.keys(resources):selected?[selected]:[];return 'KP Astrology Resources\n'+topics.map(t=>'\nTopic / subtopic: '+t+'\n'+'─'.repeat(40)+'\n'+(t===selected?draft:resources[t])+'\n').join('');}
function preview(print=false){const text=plainText(),scope=$('resource-export-scope').value,title=scope==='all'?'KP Astrology Resources':'KP Astrology Resources · '+selected;const w=window.KPNotepad.previewText(title,text,print);if(!w){status='Allow popups to preview your resource notes.';$('resource-status').textContent=status;}return w;}
async function download(){remember();const scope=$('resource-export-scope').value,text='\ufeff'+plainText(scope),filename=(scope==='all'?'KP-Astrology-Resources':selected.replace(/[^\p{L}\p{N}_-]+/gu,'-').slice(0,80)||'KP-Resource')+'.txt';try{if(window.showSaveFilePicker){const handle=await window.showSaveFilePicker({suggestedName:filename,types:[{description:'UTF-8 text file',accept:{'text/plain':['.txt']}}]});const writer=await handle.createWritable();await writer.write(text);await writer.close();status='Text file saved on your PC.';}else{const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status='Text file downloaded. Keep it in a folder on your PC.';}saveDraft();persist(status);}catch(e){status=e.name==='AbortError'?'Text-file save cancelled.':'Text-file save failed: '+e.message;$('resource-status').textContent=status;}}
function install(){const next=document.getElementById('resources');if(!next||next===root&&root.dataset.localResources)return;root=next;root.dataset.localResources='true';if(!selected){selected=Object.keys(resources)[0]||'';draft=resources[selected]||'';}root.innerHTML='<article class="card"><h2>KP Astrology Resources</h2><p>Keep reference notes by topic. Save notes in this browser or save a text file on your PC.</p><div class="resource-layout"><div><label for="resource-topic">Topic / subtopic</label><select id="resource-topic" size="15"></select><div class="resource-actions"><button id="resource-edit-topic" type="button">Edit topic</button><button id="resource-delete-topic" type="button">Delete topic</button></div><label id="resource-topic-name-label" for="resource-new-topic">New topic / subtopic</label><input id="resource-new-topic" maxlength="120"><div class="resource-actions"><button id="resource-add" type="button">Add subtopic</button><button id="resource-cancel-topic" type="button" hidden>Cancel rename</button></div></div><div><label for="resource-notes">Reference notes</label><textarea id="resource-notes" readonly placeholder="Select Edit note to add your KP astrology material…"></textarea><div class="resource-actions"><button id="resource-edit-note" type="button">Edit note</button><button id="resource-save" type="button">Save notes</button><button id="resource-delete-note" type="button">Delete note</button></div><div class="resource-actions resource-report-actions"><label for="resource-export-scope">Report / file <select id="resource-export-scope"><option value="selected">Selected topic</option><option value="all">All topics</option></select></label><button id="resource-preview" type="button">Preview</button><button id="resource-print" type="button">Print / Save PDF</button><button id="resource-download" type="button">Save text file</button></div><p id="resource-status" class="resource-status" role="status" aria-live="polite"></p></div></div></article>';
 $('resource-topic').addEventListener('change',()=>{remember();saveDraft();selected=$('resource-topic').value;draft=resources[selected]||'';editing=false;renaming=false;newTopic='';status='';render();});$('resource-notes').addEventListener('input',()=>{draft=$('resource-notes').value;});$('resource-new-topic').addEventListener('input',()=>newTopic=$('resource-new-topic').value);
 $('resource-edit-note').addEventListener('click',()=>{editing=true;render();$('resource-notes').focus();});$('resource-save').addEventListener('click',()=>{remember();saveDraft();persist('Notes saved in this browser.');editing=false;render();});
 $('resource-delete-note').addEventListener('click',()=>{if(!selected||!confirm('Delete the note for '+selected+'?'))return;resources[selected]='';draft='';editing=false;persist('Note deleted; topic retained.');render();});
 $('resource-edit-topic').addEventListener('click',()=>{remember();renaming=true;newTopic=selected;render();$('resource-new-topic').focus();});$('resource-cancel-topic').addEventListener('click',()=>{renaming=false;newTopic='';render();});
 $('resource-add').addEventListener('click',()=>{remember();const topic=newTopic.trim();if(!topic){status='Enter a topic / subtopic name.';render();return;}if(has(topic)&&(!renaming||topic!==selected)){status='That topic already exists. Select it or enter a different name.';render();return;}saveDraft();if(renaming){const replacement=Object.create(null);Object.entries(resources).forEach(([t,n])=>replacement[t===selected?topic:t]=n);resources=replacement;}else resources[topic]='';selected=topic;draft=resources[topic];newTopic='';renaming=false;editing=true;persist('Topic saved in this browser.');render();$('resource-notes').focus();});
 $('resource-delete-topic').addEventListener('click',()=>{if(!selected||!confirm('Delete '+selected+' and its note?'))return;delete resources[selected];selected=Object.keys(resources)[0]||'';draft=resources[selected]||'';newTopic='';renaming=false;editing=false;persist('Topic and note deleted.');render();});
 $('resource-preview').addEventListener('click',()=>preview());$('resource-print').addEventListener('click',()=>preview(true));$('resource-download').addEventListener('click',download);render();
}
function importTopics(topics,sourceID){
 const marker='kpResourceImportedDocument:'+sourceID;
 try{if(localStorage.getItem(marker)==='1')return 0;}catch(_){}
 if(root?.isConnected){remember();saveDraft();}
 let count=0,first='';
 for(const item of topics){
  if(typeof item.title!=='string'||typeof item.text!=='string')continue;
  let topic=item.title,index=2;
  if(has(topic)&&resources[topic]===item.text)continue;
  while(has(topic))topic=item.title+' ('+(index++)+')';
  resources[topic]=item.text;if(!first)first=topic;count++;
 }
 if(first&&(!selected||TOPICS.includes(selected)&&!draft)){selected=first;draft=resources[selected];}
 persist(count+' reference topics added.');
 try{localStorage.setItem(marker,'1');}catch(_){}
 install();if(root?.isConnected)render();return count;
}
window.KPResources=Object.freeze({install,preview,plainText,download,importTopics});
})();
